CREATE TABLE invoice_attempts (account_id VARCHAR(64) NOT NULL REFERENCES accounts(id), request_id VARCHAR(64) NOT NULL, amount INTEGER NOT NULL CHECK (amount > 0), wallet_id VARCHAR(64) NOT NULL, state VARCHAR(16) NOT NULL CHECK (state IN ('issuing', 'uncertain', 'recorded')), payment_hash VARCHAR(64) UNIQUE, created_at DATETIME NOT NULL, PRIMARY KEY (account_id, request_id));
